@Override
public List<EncodingResult> detect(TikaInputStream tis, Metadata metadata, ParseContext parseContext) throws IOException {
    if (metaDetector != null) {
        return detectWithMeta(tis, metadata, parseContext);
    }
    return detectFirstMatch(tis, metadata, parseContext);
}
